      tindakanHPR: raw["Tindakan terhadap HPR"] || raw["Tindakan HPR"] || "",
      tindakanKasus: raw["Tindakan terhadap Korban"] || raw["Tindakan Kasus"] || "",
      tindakanMasyarakat: raw["Tindakan Masyarakat"] || "",
      rekomendasi: raw["Rekomendasi"] || "",
