      fotoDokumentasi: raw["Foto Dokumentasi"] || "",
      timKetua: raw["Ketua Tim"] || "",
      timAnggota: raw["Anggota Tim"] || "",
      tanggalPelaksanaan: raw["Tanggal Pelaksanaan"] || new Date().toISOString().slice(0, 10),
